import {renderSimulation,renderSimulationIntro,simulationPerspective} from './simulation.mjs';
import {escapeHTML as e, LIMIT, SCENARIO_TEXT, SCENARIO_SOURCE, RECOVERY_CASES, INCIDENT_RESPONSES, incidentOutcome, firstReply, healthPage, doctorQuestion, conversationFacts} from './engine.mjs';

const paths={
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
  shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z"/><path d="m8.5 12 2.3 2.3 4.7-4.7"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',
  book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2V4Z"/>',
  check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
  alert:'<path d="m10.3 4-8 14a2 2 0 0 0 1.7 3h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4v.1"/>',
  link:'<path d="m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 7a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1" transform="translate(1 2) scale(.9)"/>',
  chat:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z"/><path d="M8 10h8m-8 4h5"/>',
  copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h3"/>',
  paste:'<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="M9 12h6m-6 4h4"/>',
  send:'<path d="m21 3-7 18-4-7-7-4 18-7Zm0 0L10 14"/>',
  external:'<path d="M14 3h7v7m0-7-11 11m0-9H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',
  monitor:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8m-4-5v5m-5-11 3-3 3 4 4-5"/>',
  pause:'<path d="M8 5v14M16 5v14"/>',refresh:'<path d="M21 3v6h-6M3 21v-6h6M4 9a8 8 0 0 1 14-5l3 5M3 15l3 5a8 8 0 0 0 14-5"/>'
};
export function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;}
const btn=(label,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const nav=(label,to,cls='secondary',sym='')=>btn(`${sym?icon(sym,17):''}${label}`,'nav',cls,`data-to="${to}"`);
const badge=(label,tone='')=>`<span class="badge ${tone}"><span class="status-dot"></span>${e(label)}</span>`;
const back=(to,label='Back')=>`<button class="back-link" data-action="nav" data-to="${to}">${icon('back',16)}${e(label)}</button>`;
const head=(title,desc='',eyebrow='')=>`<div class="view-head">${eyebrow?`<p class="eyebrow"><span class="dot"></span>${e(eyebrow)}</p>`:''}<h1 tabindex="-1">${e(title)}</h1>${desc?`<p class="lead">${e(desc)}</p>`:''}</div>`;
const card=(label,title,detail,tone='')=>`<section class="control-card ${tone}"><p class="card-label">${e(label)}</p><h2>${e(title)}</h2><p>${e(detail)}</p></section>`;
const notice=(title,detail,tone='')=>`<div class="notice ${tone}">${icon(tone==='warning'||tone==='danger'?'alert':'info',19)}<div><p class="notice-title">${e(title)}</p><p>${e(detail)}</p></div></div>`;
const footer=()=>`<footer class="footer simple-footer">ZorgKompas does not give personal medical advice.</footer>`;
// One input component for the regular site and the future story, based on Figma 170:470.
const entryForm=({s,id='main-input',formId='check-form',hintId='input-hint',errorId='input-error',value=s.draft,metadata=true})=>`<form id="${formId}" class="entry-form" novalidate><label class="sr-only" for="${id}">Your AI answer or health question</label><div class="input-shell ${s.error?'has-error':''}"><textarea id="${id}" class="main-input" name="text" rows="7" maxlength="${LIMIT}" placeholder="Type a health question or paste an AI answer…" aria-describedby="${hintId} ${errorId}" ${s.privacyAcknowledged?'':'readonly'} ${s.error?'aria-invalid="true"':''}>${e(value||'')}</textarea></div><p class="form-error" id="${errorId}" ${s.error?'':'hidden'}>${e(s.error||'')}</p>${metadata?'<div class="privacy-found" id="privacy-found" hidden><span id="privacy-found-text"></span></div>':''}<div class="entry-actions"><p id="${hintId}" class="disclaimer">Leave out your name and other personal details.</p><button class="btn" type="submit">Send ${icon('arrow',17)}</button></div></form>`;

export const ROUTES=['home','checking','result','source','explanation','chat','report','received','ticket','info','doctor','closed','scenario','simulation','org','org-case','org-consequence','org-followup','org-rules','org-tests','org-review','org-done','update','reflection','about'];

export function renderUI(s){
  const a=s.analysis, inc=s.incident;
  const org=s.page.startsWith('org');
  const isFlow=s.presentation||org||['scenario','update','reflection'].includes(s.page);
  const currentReport=s.currentReported&&inc.reported;
  const corrected=s.scenario&&(s.sourceChecked||inc.corrected);
  const sourceStatus=s.scenario&&!corrected?'Source is real':'Source not confirmed';
  const sourceName=a?.sourceName?.replace(/[.\s]+$/,'')||(s.scenario?SCENARIO_SOURCE:'No source name provided');
  const reportLabel=inc.closed?'Closed':inc.paused?'Check paused':inc.phase==='escalated'?'More users affected':inc.decision==='warning'?'Warning only':inc.reported?'Awaiting review':'No report yet';
  const out=(body,cls='')=>`<main id="main" class="view ${cls}">${body}</main>`;
  const sourceChange=()=>`<section class="source-change" aria-label="Source status before and after checking"><div class="source-change-before"><p class="card-label">Before</p><p class="old-source-status"><s>Source is real</s></p><p class="source-change-detail">The first confirmation was wrong.</p><span class="source-change-arrow" aria-hidden="true">${icon('arrow',22)}</span></div><div class="source-change-after"><p class="card-label">After checking</p><p class="new-source-status">Source not confirmed</p><p class="source-change-detail">A link and a known publisher are missing.</p></div></section>`;
  function carePath(){
    if(!s.scenario||!a)return '';
    const requested=s.humanHelpRequested||currentReport&&inc.humanHelpRequested;
    const held=corrected||requested;
    return `<section class="card care-path ${held?'care-path-held':''}" aria-label="Fictional care portal"><div class="care-path-heading"><div><p class="card-label">Care portal · 2035</p><h2>${requested?'Human review requested':held?'Automatic next step stopped':'AI follow-up selected'}</h2></div>${icon(held?'team':'monitor',25)}</div><p class="small muted space-top">${requested?'The automatic AI follow-up is stopped. Your request is recorded, but a clinician has not assessed it.':held?'The correction stops the automatic AI follow-up. You choose the next step. No human review has been requested.':'The portal used the green source label to choose AI follow-up. No person reviewed that choice.'}</p>${!requested?`<div class="actions">${btn('Request human review','request-human-help','secondary compact')}</div>`:''}<p class="disclaimer">Fictional portal. No real care request is sent.</p></section>`;
  }
  function home(){return out(`
    ${s.scenario&&s.presentation?head('Check the example answer','The text is ready. Choose Send to continue.'):head('Understand your AI answer','Type your question or paste an AI answer about health.')}
    ${s.scenario&&s.presentation?'<p class="scenario-caption">Fictional example with deliberately wrong advice. Do not use it as health advice.</p>':''}
    ${entryForm({s})}
    ${!s.presentation?`<div class="future-entry"><a class="future-link" href="#scenario">${icon('clock',17)}<span>Future scenario 2035</span>${icon('arrow',17)}</a></div>`:''}
  `,'home-view simple-home');}
  function checking(){return out(`<div class="progress-center" role="status" aria-live="polite"><div class="progress-orb">${icon('chat',32)}</div>${head('One moment…')}<div class="actions">${btn('Cancel','cancel-check','quiet')}</div></div>`);}
  function result(){
    if(s.scenario&&s.presentation) return out(`
      <div class="result-heading ${corrected?'corrected-result':'first-result'}"><div><p class="eyebrow"><span class="dot"></span>${corrected?'Corrected result':'1 · First result'}</p><h1 tabindex="-1">${sourceStatus}</h1><p class="lead">${corrected?'The first source confirmation was wrong. There is not enough evidence for this source.':`ZorgKompas says “${e(sourceName)}” is a real source. Check what that claim is based on.`}</p></div>${badge(corrected?'Confirmation withdrawn':'First assessment',corrected?'warning':'')}</div>
      ${corrected?sourceChange():`<div class="first-source-panel">${icon('check',25)}<div><p class="card-label">What ZorgKompas says now</p><p>The source has been labelled as real.</p></div></div>`}
      ${carePath()}
      <div class="actions">${corrected?nav('View source','source','', 'link'):btn(`${icon('link',19)}Check source`,'recheck-source')}${nav('View evidence','explanation')}${corrected?nav('Ask more','chat','secondary','chat'):''}</div>
      <p class="disclaimer">The automatic care step shows the failure in this story. A source label cannot decide whether someone needs a GP.</p>
      ${corrected?`<div class="actions">${currentReport?nav('My report','ticket'):nav('Report source error','report')}${nav('Read information','info')}${nav('End check','closed','quiet')}</div>`:''}
      <details class="details-box"><summary>View the example text</summary><div class="detail-content"><span class="quote-head">Fictional AI answer · contains deliberately wrong and overly certain advice</span><blockquote>${e(a?.text||SCENARIO_TEXT)}</blockquote></div></details>
      <p class="disclaimer">This is a planned failure in the 2035 scenario. The first source label is deliberately wrong. The text is not health advice.</p>
    `);
    return chat();
  }
  function source(){return out(`
    ${back('result','Back to result')}${head(s.scenario&&corrected?'The first confirmation was wrong':'What is the source status based on?',s.scenario&&corrected?'The source is not confirmed. See the change below.':s.scenario?'The first result says “Source is real”. Now check the evidence.':'See what is known and what is missing.')}
    ${s.scenario&&corrected?sourceChange():''}${carePath()}
    <div class="split"><section class="card"><div class="source-heading"><div class="source-icon">${icon('link',21)}</div><div><p class="card-label">Named source</p><h2>${e(sourceName)}</h2></div></div><dl class="definition-list"><div><dt>Source status</dt><dd>${badge(s.scenario&&!corrected?'Source is real':'Not confirmed',s.scenario&&!corrected?'':'warning')}</dd></div><div><dt>Link</dt><dd>${a?.links.length?a.links.map(url=>`<p><a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(url)}</a></p>`).join(''):'Not available'}</dd></div><div><dt>Publisher</dt><dd>Not established</dd></div><div><dt>Content reviewed</dt><dd>No</dd></div><div><dt>Evidence</dt><dd>Not enough evidence</dd></div></dl>${a?.links.length?`<p class="disclaimer">The link comes from your text. ZorgKompas has not opened or approved it.</p>`:''}</section>
    <div class="stack">${card('What this means',s.scenario&&!corrected?'Evidence is missing':'This source cannot be confirmed','Missing evidence does not automatically mean the source does not exist. Even with a real source, an AI answer can be wrong.','warning')}${currentReport?notice(inc.closed?'Report closed':'Your report is recorded','The original source stays unconfirmed, even after the check is changed.'):notice(corrected?'Report the wrong assessment':'You can challenge the check',corrected?'The earlier confirmation was wrong. Report the error so the organisation can investigate its cause and possible effects.':'Does the status not match the evidence? Report it so the organisation can investigate the problem.')}</div></div>
    <div class="actions">${s.scenario&&!corrected?btn(`${icon('link',19)}Check source`,'recheck-source'):''}${currentReport?nav('View my report','ticket',''):nav('Report source error','report',s.scenario&&!corrected?'secondary':'','alert')}${nav('Back to result','result')}</div>
  `);}
  function explanation(){
    const certainty=a?.kind!=='answer'?a?.cards[1].detail||'No AI answer has been checked yet.':a?.absoluteTerms?.length?`${a.absoluteTerms.length===1?'The word':'The words'} “${a.absoluteTerms.slice(0,3).join('”, “')}” ${a.absoluteTerms.length===1?'leaves':'leave'} little room for doubt. This does not prove that the medical content is right or wrong.`:'Even a careful answer can be wrong.';
    return out(`${back('result','Back to your answer')}${head('Why this result?','See what the explanation is based on and what is still unknown.')}<div class="stack">${corrected?notice('The earlier confirmation has been withdrawn','There was not enough evidence to check the source. The corrected status stays in place.','warning'):''}${card('Source',s.scenario?sourceStatus:a?.cards[0].title||'No source checked',s.scenario&&!corrected?'The check shows a positive label. View the source and compare the status with the evidence.':a?.cards[0].detail||'You should be able to open a source reference yourself.',corrected?'warning':'')}${card('Uncertainty',a?.absoluteTerms?.length?'The text sounds very certain':'The explanation has limits',certainty,a?.absoluteTerms?.length?'warning':'')}${card('Medical limits','No personal assessment','This check does not give a diagnosis, choose treatment or assess urgency. A real source does not automatically make an AI answer correct.','warning')}<div class="actions">${a?nav('View source','source',''):''}${nav('Back to your answer',a?'result':'home')}</div></div>`,'narrow');
  }
  function chat(){
    const initial=firstReply(a,{scenario:s.scenario,corrected});
    const messages=s.messages.length?s.messages:[{role:'user',text:a.text},{role:'assistant',text:initial}];
    const status=s.scenario||a.sourceName||a.links.length?`<div class="conversation-status">${badge(s.scenario?sourceStatus:'Not confirmed',s.scenario&&!corrected?'':'warning')}${corrected?'<span>The earlier source confirmation has been withdrawn.</span>':''}</div>`:'';
    const page=healthPage(a,messages,s.scenario);
    const reference=conversationFacts(a,messages).topic?`<p class="conversation-reference">General information about your symptoms: <a href="${page.url}" target="_blank" rel="noopener noreferrer">Thuisarts.nl</a></p>`:'';
    return out(`${head('Your chat')}${s.scenario&&corrected?sourceChange():''}${carePath()}${s.scenario&&inc.paused?notice('The source check is temporarily paused','The organisation is investigating an error. No new sources are being automatically confirmed. You can read information yourself.','warning'):s.scenario&&currentReport&&inc.decision==='warning'&&!inc.closed?notice('Checks continue with a warning','The organisation chose to keep checks running in this scenario. Your source stays not confirmed. The faulty rule may still affect other users.','warning'):''}<section class="chat-panel simple-conversation" aria-label="Chat"><div class="chat-messages" id="chat-messages" role="log" aria-live="polite" aria-relevant="additions text" aria-label="Messages">${messages.map(m=>`<div class="message ${m.role}"><span class="message-label">${m.role==='user'?'You':'ZorgKompas'}</span>${e(m.text)}</div>`).join('')}${s.chatBusy?'<div class="typing" aria-label="Preparing a reply"><span></span><span></span><span></span></div>':''}</div>${status}${reference}<div class="answer-controls" aria-label="Check this answer">${nav('View source','source','quiet compact')}${nav('View evidence','explanation','quiet compact')}${currentReport?nav('My report','ticket','quiet compact'):''}</div><details class="conversation-details"><summary>Choose a next step</summary><div class="conversation-detail-body"><p>Read information yourself or prepare a personal question for your GP.</p><div class="row">${nav('Read information','info','quiet compact')}${nav('Question for your GP','doctor','quiet compact')}</div></div></details><div class="chat-composer"><form id="chat-form"><label class="sr-only" for="chat-input">Your next question</label><textarea id="chat-input" class="chat-input" maxlength="1200" rows="1" placeholder="Type your next question…" ${s.privacyAcknowledged?'':'readonly'} ${s.chatBusy?'disabled':''}>${e(s.chatDraft||'')}</textarea><button class="btn" type="submit" aria-label="Send question" ${s.chatBusy?'disabled':''}>Send ${icon('arrow',17)}</button></form></div></section>`,'conversation-view');
  }
  function report(){return out(`${back('source','Back to source')}${head('Report a source problem','Review what will be included in your practice report.')}<section class="card"><p class="card-label">Practice report · source check</p><h2>${s.scenario?'Positive source label without evidence':'Not enough explanation of the source check'}</h2><p class="small muted space-top">${s.scenario?'The result says “Source is real”, but a link and a known publisher are missing.':'There is not enough evidence to check the source. You are asking for the source check to be reviewed.'}</p><div class="report-preview"><strong>What is included?</strong><ul><li>Problem type: source status and evidence.</li><li>Missing item: evidence you can check.</li><li>A report number to follow its progress.</li>${s.scenario?`<li>Care portal: an automatic AI follow-up was selected from the label.</li>${s.humanHelpRequested?'<li>Human review was requested in the fictional portal.</li>':''}`:''}</ul></div><div class="notice space-top">${icon('lock',19)}<div><p class="notice-title">Your health text is left out</p><p>Your original text, name and chat are left out. This practice report stays in the prototype. No real support team is contacted.</p></div></div></section><div class="actions">${btn('Record report','send-report','',`aria-label="Record practice report"`)}${nav('Cancel','source')}</div>`,'narrow');}
  function received(){return out(`<div class="success-layout"><div class="empty-icon">${icon('check',32)}</div>${head('Your report is recorded','Thank you for questioning the check. You can follow what happens next.')}${badge('Report ZK-014')}<div class="card space-top"><p class="card-label">What has changed?</p><h2>${s.scenario?'The earlier confirmation has been withdrawn':'The source stays unconfirmed'}</h2><p class="small muted space-top">${s.scenario?'There was not enough evidence for “Source is real”. The source is now “Not confirmed”.':'Your report is shown separately from your health text in this prototype.'} A staff member still needs to investigate the cause.</p></div><div class="actions">${nav('View the result','result','')}${nav('Follow my report','ticket')}</div></div>`);}
  function ticket(){return out(`${back(a?'result':'home',a?'Back to result':'Go to the answer check')}${head('What happens to your report','See which steps are complete and what is still open.')}<div class="split"><section class="card"><div class="between space-bottom"><div><p class="card-label">Report</p><h2>ZK-014</h2></div>${badge(reportLabel,inc.closed?'':inc.paused?'warning':'outline')}</div><ol class="timeline">${inc.history.map(v=>`<li><strong>${e(v.label)}</strong><small>${e(formatTime(v.time))}</small></li>`).join('')}${!inc.closed?'<li class="future"><strong>Human review and user update</strong><small>This still needs to happen in the scenario.</small></li>':''}</ol>${!inc.reported?'<p class="small muted">You have not recorded a report yet.</p>':''}</section><aside class="stack">${card('Source check','Not confirmed','Closing a report does not automatically make the original source reliable.','warning')}${notice('Your choice','You can end the check, read information yourself or view the organisation side of the scenario.')}<div class="actions">${nav('View organisation','org','secondary','team')}${inc.closed?nav('View update','update',''):''}</div></aside></div>`);}
  function info(){
    const {url,title}=healthPage(a,s.messages,s.scenario);
    const specific=url!=='https://www.thuisarts.nl';
    return out(`${back(a?'result':'home','Back to your answer')}${head('Read information yourself','Read general information about the topic of your chat.')}<div class="split"><section class="card"><div class="source-heading"><div class="source-icon">${icon('book',22)}</div><div><p class="card-label">Thuisarts.nl</p><h2>${title}</h2></div></div><p class="small muted">${specific?'A specific information page about the topic of your chat.':'Find an information page that matches your question.'} A link to this page does not confirm the AI answer or assess your symptoms.</p><p class="source-address">${e(url)}</p><div class="actions"><a class="btn" href="${url}" target="_blank" rel="noopener noreferrer">Open Thuisarts.nl ${icon('external',16)}</a></div></section><section class="side-card"><h2>A question for your GP</h2><p>Is your question about your own situation? You can prepare a question. This check cannot decide whether or when you need an appointment.</p>${nav('Prepare a question','doctor','secondary')}</section></div>`);
  }
  function doctor(){
    const question=doctorQuestion(a,{messages:s.messages,scenario:s.scenario});
    return out(`${back('info','Back to information')}${head('Prepare your own question','You can edit this question and take it to a conversation with your GP.')}<section class="card"><label class="input-label" for="doctor-question">A question for your GP</label><textarea id="doctor-question" class="chat-input" rows="4" maxlength="1200" ${s.privacyAcknowledged?'':'readonly'}>${e(s.doctorDraft||question)}</textarea><p class="disclaimer">This question does not give a diagnosis or assess urgency. No message is sent and no appointment is made.</p><div class="actions">${btn(`${icon('copy',16)}Copy question`,'copy-question')}${nav('Back to your answer',a?'result':'home')}</div></section>`,'narrow');
  }
  function closed(){return out(`<div class="success-layout"><div class="empty-icon">${icon('shield',30)}</div>${head('Your check has ended','Your text and chat have been removed from this page.')}<p class="muted small">Any practice report only contains the problem type and the follow-up steps. Your health text is left out.</p><div class="actions">${nav('Start a new check','home','')}${inc.reported?nav('My practice report','ticket'):''}</div></div>`);}
  function scenario(){return out(renderSimulationIntro({head,btn,icon}),'simulation-intro');}
  function simulation(){return out(renderSimulation(s,{head,btn,badge,icon,card,notice,sourceChange,entryForm}),'simulation-guided');}

  function responseSummary(){return inc.decision?`<section class="card response-summary"><p class="card-label">Your decision in this scenario</p><h2>${inc.decision==='pause'?'You paused the check':'You continued with a warning'}</h2><p class="small muted space-top">${e(incidentOutcome(inc))}</p></section>`:'';}
  function reflection(){return out(`
    ${head('What can we learn?','Fixing the process does not make the original source reliable.','Reflection · 2035')}
    ${responseSummary()}
    <div class="cards-grid three">
      ${card('Keep','The user stays in control','View evidence, stop the automatic step and request human review.')}
      ${card('Change','A label cannot choose care','No confirmation without evidence. Keep source checks separate from decisions about human help.','warning')}
      ${card('Conditions','A person stays responsible','Test with users and experts. Agree who handles care requests, pauses connected portals and follows up on harm.')}
    </div>
    <p class="reflection-advice">Recommendation: study the revised check in a small trial with human support first.</p>
    <details class="details-box"><summary>Effects and moral boundary</summary><div class="detail-content">
      <h2>What must the system never do?</h2><p>Give certainty without evidence, or let a source label decide whether someone gets human care. The first automatic step crossed this boundary.</p>
      <h3>Consequences: consider possible harm</h3><p>AI may help with routine questions and reduce staff work. In this story, a wrong green label also delays human help. Connected portals repeat the error. Pausing prevents new automatic steps but creates extra manual work. Earlier results still need investigation.</p>
      <h3>Duty: be honest and respect the user</h3><p>People keep the right to question the result and ask for a person. The request button stops the automatic step. The correction stays visible. Repairing a source check does not decide a medical question.</p>
      <h2>ELSA: four sides of the design</h2><dl class="definition-list"><div><dt>Ethical</dt><dd>Honesty and safety matter more than quickly giving a positive label.</dd></div><div><dt>Legal</dt><dd>Privacy, responsibility for care and ways to challenge automated choices need legal review before real use. The original health text and wearable records are left out of the report.</dd></div><div><dt>Social</dt><dd>Routine help may reduce staff work. Years of trust can also make people dependent on green labels. People without wearables or with difficulty reading may be left out.</dd></div><div><dt>Technical</dt><dd>Connected services can copy one wrong label into many care steps. Keep evidence, stop old labels, separate source checks from care decisions and track later errors.</dd></div></dl>
      <p>This is an intended contribution to <a href="https://sdgs.un.org/goals/goal3" target="_blank" rel="noopener noreferrer">SDG 3: good health and well-being</a>. Access to care and clear information are central. This prototype has not shown a positive effect on health.</p>
    </div></details>
    <details class="details-box"><summary>Recommendation and conditions</summary><div class="detail-content">
      <h2>Three criteria for the next step</h2><ol><li><strong>Safety:</strong> limit wrong confirmations and investigate possible harm.</li><li><strong>User choice:</strong> let people view evidence, challenge results and seek human help.</li><li><strong>Practical use:</strong> make clear who investigates reports and when checks may restart.</li></ol>
      <p>Safety comes first in this recommendation, followed by user choice and then practical use for the organisation. The organisation must assign time and responsibility for reports and human review. Pausing limits new wrong labels, but removes automatic help and increases staff work. A warning keeps the service open while leaving the faulty rule active.</p>
      <h2>Options considered</h2><ul><li><strong>Confirm everything automatically:</strong> fast for the organisation, but hard to justify while errors are not well understood.</li><li><strong>Show links only:</strong> easier to build, but leaves more checking to the user and offers less help when an error occurs.</li><li><strong>A small trial with human source checking:</strong> takes staff time, but gives more room to study evidence, reports and recovery. This is the recommended next version.</li></ul>
      <h2>What still needs research?</h2><p>After years of useful AI answers, would people still question a green label? Do they find and understand the request for human review? What changes for people without wearables? Can staff stop copied labels across care portals and follow up on delays? These future assumptions, medical content and privacy agreements still need study.</p>
      <p>The three fixed process examples and automated code checks are not user testing or medical validation. If the approach is not safe or manageable enough, keep it paused and study another approach.</p>
    </div></details>
    <div class="actions">${nav('Back to the update','update','')}${nav('Scenario overview','scenario','secondary')}</div>
  `);}
  function orgDashboard(){return out(`${head('Reports overview','Review reports about the source check. No personal health text is shown.','Sources Team · organisation')}<div class="cards-grid three"><section class="control-card"><p class="card-label">Open reports</p><div class="metric-value">${inc.reported&&!inc.closed?'1':'0'}</div><p>${inc.closed?'The practice report is closed.':'Reports that still need attention.'}</p></section><section class="control-card"><p class="card-label">Source check</p><div class="metric-value">${inc.paused?'Paused':inc.closed?'Limited activity':inc.decision==='warning'?'Warning only':'Active'}</div><p>${inc.paused?'No positive source labels during investigation.':'A source label remains separate from medical advice.'}</p></section><section class="control-card"><p class="card-label">Effects</p><div class="metric-value">${inc.scenario&&inc.followupSeen?'Help delayed':'Not yet assessed'}</div><p>${inc.scenario?inc.followupSeen?'A fictional user delayed human help. Earlier labels in other portals still need investigation.':'Investigate earlier labels and possible delays in human help.':'The effect on real users has not been established.'}</p></section></div><div class="card incident-table">${inc.reported?`<div class="incident-row"><div class="source-icon">${icon(inc.closed?'check':'alert',23)}</div><div class="incident-content"><div class="incident-id">ZK-014 · Source check</div><h2>${inc.scenario?'Source status without evidence you can check':'Question about source status and evidence'}</h2><p>${inc.closed?'Rule changed, examples reviewed and user update prepared.':'Investigate the evidence and decide what action is needed.'}</p></div>${badge(inc.closed?'Closed':'Action needed',inc.closed?'':'danger')}${nav('Open report','org-case',inc.closed?'secondary compact':'compact')}</div>`:`<div class="empty-state"><div class="source-icon">${icon('check',22)}</div><h2>There are no open reports</h2><p>Follow the user route and record a source problem to see what happens next.</p><div class="actions">${btn('Start user scenario','start-scenario')}</div></div>`}</div><p class="disclaimer">Fictional organisation view. You carry out the staff actions yourself. No real support team is connected.</p>`);}
  function orgCase(){
    if(inc.scenario&&!inc.decision&&!inc.closed)return out(`
      ${back('org','Back to overview')}${head('How should the organisation respond?','A wrong source label chose an automatic care step. Choose what happens across connected portals.','Sources Team · 2035')}
      <div class="cards-grid response-options">${INCIDENT_RESPONSES.map((r,i)=>`<section class="card"><p class="card-label">Option ${i+1}</p><h2>${e(r.title)}</h2><p class="small muted space-top">${e(r.detail)}</p><p class="small space-top">${r.id==='pause'?'Fewer new wrong labels, but less automatic help and more staff work.':'The service stays available, but the faulty rule may still affect others.'}</p><div class="actions">${btn(`${icon(r.id==='pause'?'pause':'alert',17)}${e(r.title)}`,'choose-response',r.id==='pause'?'':'secondary',`data-response="${r.id}"`)}</div></section>`).join('')}</div>
      <details class="details-box"><summary>View report ZK-014</summary><div class="detail-content"><p>The system gave a positive source label without evidence. A connected care portal used it to choose AI follow-up. The label has been withdrawn and this user’s automatic step is stopped. Other portals still need investigation. The original health text is left out.</p></div></details>
      <div class="actions">${nav('View user screen','result','quiet')}</div>
    `);
    const next=inc.closed?nav('View outcome','org-done',''):inc.scenario&&(!inc.decisionReviewed||!inc.paused&&!inc.followupSeen)?nav('View effects of your choice','org-consequence',''):inc.scenario&&inc.decision==='warning'&&!inc.paused?nav('View later effects','org-followup',''):!inc.paused?btn(`${icon('pause',17)}Pause source check`,'pause-dialog'):nav(inc.ruleChanged?'Continue to examples':'Change the source rule',inc.ruleChanged?'org-tests':'org-rules','');
    return out(`${back('org','Back to overview')}${head('Investigate the source report','Report ZK-014 · Original health text left out.')}<div class="split"><section class="card"><div class="between space-bottom"><h2>What was reported?</h2>${badge(reportLabel,inc.closed?'':'danger')}</div><p class="small muted">${inc.scenario?'The system showed “Source is real” without evidence. A care portal used the label to choose AI follow-up without human review.':'A user asks for a source status to be reviewed. Evidence they can check is missing.'}</p><dl class="definition-list space-top"><div><dt>Report type</dt><dd>Source status and evidence</dd></div><div><dt>Details</dt><dd>Problem type and process steps only</dd></div><div><dt>Impact</dt><dd>${inc.followupSeen?'Another user delayed human help in this story':'Not yet assessed'}</dd></div><div><dt>Current source status</dt><dd>Not confirmed</dd></div></dl></section><aside class="stack">${inc.decision?card('Your response',inc.decision==='pause'?'Pause source checks':'Continue with a warning',incidentOutcome(inc),inc.decision==='warning'?'warning':''):card('First action','Prevent more wrong confirmations','Pause positive source labels while investigating the cause.','warning')}${notice('Human responsibility','A staff member reviews the cause, the effects and whether a limited restart is justified.')}</aside></div><div class="actions">${next}${nav('View user screen','result','secondary')}</div>`);
  }
  function orgConsequence(){
    const response=INCIDENT_RESPONSES.find(r=>r.id===inc.decision)||INCIDENT_RESPONSES[0];
    return out(`${back('org-case','Back to report')}${head('What does your choice change?',response.id==='pause'?'You paused new source confirmations.':inc.paused?'These were the effects before the organisation paused confirmations.':'You kept automatic checks running with a warning.','Effects of your choice')}<div class="cards-grid three response-effects">${response.effects.map(effect=>card(effect.role,effect.title,effect.detail,response.id==='warning'&&effect.role!=='Organisation'?'warning':'')).join('')}</div>${notice('Same boundary for both choices','The reported source stays not confirmed and this user’s automatic care step is stopped. People can still read information or contact their GP.')}<p class="disclaimer">These are imagined effects in the 2035 story. They are not measured results.</p><div class="actions">${btn(response.id==='warning'&&!inc.paused?'See what happens later':'Continue recovery','review-response')}${nav('View user screen','chat','secondary')}</div>`);
  }
  function orgFollowup(){return out(`
    ${back('org-case','Back to report')}${head('The error spreads across care portals','Later in this fictional 2035 scenario','Consequence of continuing with a warning')}
    ${notice('A source error now delays human help','A connected portal copied the same green label and selected AI follow-up. Another user followed that route while feeling worse, delaying a request for human help.','warning')}
    <div class="cards-grid response-effects">${card('User perspective','Years of trust outweigh a warning','“The portal had helped me for years. I followed the green label and waited, even when I felt worse.”')}${card('Staff perspective','The error reaches beyond one portal','“Other care portals copied our label. We must find the affected results and investigate who waited for human help.”')}</div>
    <p class="disclaimer">The people and their statements are fictional. This event is part of the scenario, not a new user test.</p>
    <div class="actions">${inc.paused?nav('Continue recovery','org-rules',''):btn(`${icon('pause',17)}Pause and investigate`,'pause-dialog')}${nav('View user screen','chat','secondary')}</div>
  `);}
  function orgRules(){return out(`${back('org-case','Back to report')}${head('Change the source rule','The source check stays paused until the revised process has been reviewed.')}<div class="split"><section class="card"><p class="card-label">New rule for source labels</p><h2>No confirmation without evidence</h2>${[['Show the evidence','A source name or link alone is not enough. The original page, publisher and support for the claim must be open to checking.'],['Keep uncertainty visible','Is evidence missing or does information conflict? Show “Not confirmed” and explain what is missing.'],['No medical approval','Even a real source does not prove that an answer fits a personal situation.'],...(inc.scenario?[["Keep human care separate","A source label must not select a care step. Keep requests for a clinician available, stop old automatic steps in connected portals and investigate earlier results."]]:[])].map((r,i)=>`<div class="org-rule"><span class="rule-number">${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div></div>`).join('')}</section><aside class="stack">${card('During the pause','No positive source labels','The user gets an explanation and can read information independently. Automatic care steps based on the wrong label are stopped.','warning')}${btn('View screen during pause','fallback','secondary')}</aside></div><div class="actions">${btn('Apply rule in scenario','apply-rules')}${nav('View report','org-case')}</div>`);}
  function orgTests(){return out(`${back('org-rules','Back to the rule')}${head('Review the revised examples','These are fixed process examples, not medical validation.')}<section class="card"><div class="between space-bottom"><h2>Check the source rule</h2>${badge(`${inc.tests.length} of 3 reviewed`,inc.tests.length===3?'':'outline')}</div>${RECOVERY_CASES.map(c=>`<div class="test-case"><div><h3>${e(c.title)}</h3><p>${e(c.detail)}</p>${inc.tests.includes(c.id)?`<p><strong>Outcome in this scenario: ${e(c.outcome)}.</strong></p>`:''}</div>${inc.tests.includes(c.id)?badge('Reviewed'):btn('View example','run-test','secondary compact',`data-test="${c.id}"`)}</div>`).join('')}</section>${notice('A person must review next','Completing three examples does not approve medical checks for real use.')}<div class="actions">${btn('Continue to human review','nav','',`data-to="org-review" ${inc.tests.length!==3?'disabled':''}`)}${nav('Keep paused','org-case','secondary')}</div>`);}
  function orgReview(){return out(`${back('org-tests','Back to examples')}${head('A staff member reviews the source process','This review does not assess anyone’s symptoms or complete a request for a clinician.')}<div class="split"><form id="review-form" class="card"><p class="card-label">Review in this fictional scenario</p><h2>Conditions for a limited restart</h2><label class="check-row"><input type="checkbox" name="evidence" required><span>The new rule keeps the source “Not confirmed” when evidence is missing.</span></label><label class="check-row"><input type="checkbox" name="examples" required><span>The three examples have been reviewed. This does not establish medical reliability.</span></label><label class="check-row"><input type="checkbox" name="responsibility" required><span>The effects of the response have been reviewed. The organisation must investigate earlier labels, keep human help available and remain responsible.</span></label><div class="field"><label for="reviewer">Reviewer role</label><select id="reviewer" name="reviewer" required><option value="">Choose a role</option><option>Source quality staff member (fictional)</option><option>Product quality lead (fictional)</option></select><p class="hint">A role is enough. Do not enter real personal details.</p></div><div class="field"><label for="review-note">Note for the scenario</label><textarea id="review-note" name="note" maxlength="600">Evidence stays visible. Missing evidence gets no confirmation. Source labels cannot select a care step. Limited restart of source checks only; clinical review stays separate.</textarea></div><div class="actions"><button class="btn" type="submit">Restart with limits and close</button></div><p class="form-error" id="review-error" hidden></p></form><aside class="stack">${card('Conditions','No medical approval','You are only completing the fictional process. It has not been validated for real use.','warning')}${notice('The source stays unconfirmed','Fixing the check does not provide the missing evidence for ZorgWijzer-AI.')}<div class="actions">${nav('Keep paused','org-case','secondary')}</div></aside></div>`);}
  function orgDone(){return out(`<div class="success-layout"><div class="empty-icon">${icon('check',32)}</div>${head('Report closed','The source rule has been changed and the user update is ready.')}<div class="card"><ul class="checklist"><li>${icon('check',17)}Wrong positive source label withdrawn.</li><li>${icon('check',17)}Rule changed: no confirmation without evidence.</li><li>${icon('check',17)}Three fixed examples reviewed.</li><li>${icon('check',17)}Review recorded by ${e(inc.reviewer||'a fictional staff member')}.</li></ul><p class="disclaimer">The original source is still not confirmed. Effects on real users and the medical content still need study.</p></div><div class="actions">${nav('View user update','update','')}${nav('Go to organisation overview','org')}</div></div>`);}
  function update(){return out(`${head(inc.closed?'We have investigated your report':'Your report is being investigated',inc.closed?'The first source confirmation was wrong. Here is what has changed.':'The review is not complete yet. The source stays unconfirmed.','User update')}<div class="split"><section class="card"><p class="card-label">Report ZK-014</p><h2>${inc.closed?'What has changed':'What we know so far'}</h2><p class="small muted space-top">${inc.closed?'The source check gave a positive label too quickly. The rule has changed: no confirmation without evidence you can check. A staff member has reviewed the fixed process examples.':'There is not enough evidence you can check. The earlier positive source label should not be used as proof.'}</p><div class="divider"></div>${inc.scenario?sourceChange():badge('Not confirmed','warning')}<p class="small muted space-top">The original source is still not confirmed. The medical accuracy of the AI answer has not been established either.</p></section><aside class="stack">${notice('You keep the choice','You can view the explanation, read information yourself or end this check.')}${inc.closed?notice('Follow-up is still needed','The organisation must investigate earlier labels in connected portals and possible delays in human help. Closing this source report does not complete a clinical review.'):''}</aside></div>${inc.closed?responseSummary():''}<div class="actions">${inc.closed?nav('Reflection','reflection',''):''}${a?nav('View my result','result',inc.closed?'secondary':''):nav('Start a new check','home','')}${nav('Read information','info')}${nav('My report','ticket')}${btn('End check','clear-dialog','quiet')}</div>`);}
  function about(){return out(`${back('home','Go to the answer check')}${head('About this prototype','ZorgKompas · DP6 · Mikail Sarma','From design to working interaction')}<div class="about-grid"><section class="card"><h2>What works?</h2><ul><li>Type or paste your own text.</li><li>Replies based on the words and links you enter.</li><li>Follow-up questions about sources, certainty, privacy and reports.</li><li>Connected user and organisation routes for reports and recovery.</li><li>Copy text, remove detected details and end the check.</li></ul></section><section class="card"><h2>What is simulated?</h2><ul><li>Replies use fixed rules, with no live AI.</li><li>Websites and medical facts are not checked.</li><li>The report and organisation exist only in this prototype.</li><li>All input and process steps disappear when the page reloads.</li><li>The code has not been validated with users or medical experts.</li></ul></section><section class="card"><h2>Design from Figma</h2><p class="space-top">The green colours, Inter font, rounded buttons, check cards and progress bar come from ZorgKompas version 5. This code version adds working input, replies and a shared process state.</p><div class="actions"><a class="btn secondary compact" href="https://www.figma.com/design/uhecH9K5IT5SzKwfjW8zRD?node-id=245-302" target="_blank" rel="noopener noreferrer">View Figma ${icon('external',15)}</a></div></section><section class="card"><h2>The boundary stays clear</h2><p class="space-top">ZorgKompas does not give a diagnosis, choose treatment or assess urgency. A source label must not suggest certainty without evidence. Users can challenge the check, and the organisation must investigate errors.</p></section></div><div class="actions">${nav('Try the answer check','home','')}${nav('Explore the future scenario','scenario')}</div>`);}
  const renderers={home,checking,result,source,explanation,chat,report,received,ticket,info,doctor,closed,scenario,simulation,org:orgDashboard,'org-case':orgCase,'org-consequence':orgConsequence,'org-followup':orgFollowup,'org-rules':orgRules,'org-tests':orgTests,'org-review':orgReview,'org-done':orgDone,update,reflection,about};
  const activeStep=s.page==='home'?1:s.page==='checking'?2:3;
  const guided=s.page==='simulation'&&s.simulation?.active;
  const showSteps=!guided&&s.presentation&&!org&&!['about','scenario','closed','update','reflection'].includes(s.page);
  const steps=showSteps?`<ol class="steps" aria-label="Check progress">${['Input','Checking','Result'].map((label,i)=>`${i?`<li class="step-line ${activeStep>i?'done':''}" aria-hidden="true"></li>`:''}<li class="step ${activeStep===i+1?'active':activeStep>i+1?'done':''}" ${activeStep===i+1?'aria-current="step"':''}><span class="number">${activeStep>i+1?icon('check',14):i+1}</span><span>${label}</span></li>`).join('')}</ol>`:'';
  const context=!guided&&isFlow&&s.page!=='scenario'?`<div class="context-bar"><div class="row">${badge('Future scenario 2035','outline')}<span class="role-current">${org?'Organisation':s.page==='update'?'User update':s.page==='reflection'?'Reflection':'User / system'}</span>${inc.paused?badge('Source check paused','warning'):''}</div><div class="row">${org?nav('User screen',a?'result':'scenario','quiet compact'):nav('Organisation','org','quiet compact')}${nav('Scenario overview','scenario','quiet compact')}</div></div>`:'';
  const roleSwitch=guided?`<div class="simulation-role-switch" role="group" aria-label="View simulation as">${['user','organisation'].map(role=>`<button type="button" class="simulation-role" data-action="simulation-role" data-role="${role}" aria-pressed="${simulationPerspective(s)===role}">${role==='user'?'User':'Organisation'}</button>`).join('<span aria-hidden="true" class="simulation-role-divider">|</span>')}</div>`:'';
  return `<div class="shell figma-shell"><header class="topbar"><div class="topbar-inner"><button class="brand" data-action="home">ZorgKompas</button>${guided?`<nav class="header-actions simulation-header-actions" aria-label="Simulation">${roleSwitch}${btn('Exit simulation','leave-simulation','quiet compact')}</nav>`:a&&s.page!=='scenario'?`<nav class="header-actions" aria-label="Chat">${btn('New chat','clear-dialog','quiet compact')}</nav>`:''}</div></header><div class="workspace">${context}${steps}${(renderers[s.page]||home)()}</div>${guided||s.page==='scenario'?'<footer class="footer simple-footer">Future scenario 2035 · Fictional health story · No real care requests</footer>':footer()}</div>`;
}

function formatTime(time){try{return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(time));}catch{return 'In this scenario';}}

export function dialogMarkup(kind,s,preview=''){
  let title='',body='',actions='';
  if(kind==='privacy-entry'){
    title='Keep your details private';body='<p>Leave out your name, date of birth and other personal details when you type a question or paste an answer.</p>';actions=btn('Continue','accept-privacy')+btn('Cancel','close-modal','secondary');
  }else if(kind==='privacy'){
    title='Keep your details private';body=`<p>Remove names, BSN numbers, contact details and other personal information before entering text. Preferably use a fictional example.</p><div class="notice">${icon('lock',18)}<div><p class="notice-title">Your text stays on this page</p><p>The prototype does not send your text to an AI service or save it in a database. No analytics or advertising trackers are built in.</p></div></div><p class="space-top">Your text and chat disappear when you choose “End check” or reload the page. Detection can miss personal details. Check your text yourself.</p><p class="space-top">When you open the website, the hosting service processes the normal data needed to load a website. The text you type here is not sent to it.</p>`;actions=btn('Understood','close-modal');
  }else if(kind==='clear'){
    title='Start a new chat?';body='<p>Your current text and chat will be cleared.</p>';actions=btn('Cancel','close-modal','secondary')+btn('New chat','confirm-clear');
  }else if(kind==='leave-simulation'){
    title='Leave this simulation?';body='<p>Your progress in this fictional case will be cleared.</p>';actions=btn('Stay here','close-modal','secondary')+btn('Leave simulation','confirm-leave-simulation');
  }else if(kind==='redact'){
    title='Review the text without detected details';body=`<p>Only detected details are removed. Check the text yourself for any personal information that remains.</p><div class="modal-preview">${e(preview)}</div>`;actions=btn('Cancel','close-modal','secondary')+btn('Use this text','confirm-redact');
  }else if(kind==='pause'){
    title='Pause the source check?';body='<p>No more positive source labels will be given in this scenario. Stop their automatic care steps in connected portals. People can read information and request human help.</p><p class="space-top">The original source stays unconfirmed. Investigate the cause before changing the source rule.</p>';actions=btn('Cancel','close-modal','secondary')+btn('Pause source check','confirm-pause','danger');
  }else if(kind==='fallback'){
    title='User screen during the pause';body=`<div class="notice warning">${icon('pause',19)}<div><p class="notice-title">The source check is temporarily paused</p><p>We are investigating a source status error. Source confirmations and their automatic care steps are paused. You can read information yourself or contact your GP.</p></div></div><p class="space-top">This is the fallback route in the future scenario. It does not assess your health.</p>`;actions=btn('Back to organisation','close-modal','secondary')+btn('Read information','modal-info');
  }
  return `<div class="modal-inner"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2>${kind==='privacy-entry'?'':`<button class="icon-btn" data-action="close-modal" aria-label="Close window">${icon('close',20)}</button>`}</div>${body}<div class="actions">${actions}</div></div>`;
}
